"""Resolve complete A-share scopes without changing the native trading method."""
from __future__ import annotations

import hashlib
import json
import re
from datetime import datetime
from pathlib import Path
from typing import Any
from zoneinfo import ZoneInfo

from fastapi import HTTPException

_PAGE_SIZE = 100
_BOARD = re.compile(r"^BK[0-9]{4,8}$")


class ScopeUnavailableError(ValueError):
    def __init__(self, code: str, note: str):
        super().__init__(code)
        self.code = code
        self.note = note


def _stamp() -> str:
    return datetime.now(ZoneInfo("Asia/Shanghai")).isoformat()


def _hash(value: Any) -> str:
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True,
        separators=(",", ":"), allow_nan=False).encode("utf-8")).hexdigest()


def validate_scope(scope: Any) -> dict[str, Any]:
    from src.api.mona_backtest_settings import _symbol

    if not isinstance(scope, dict) or scope.get("kind") not in {"all_a", "industry", "watchlist"}:
        raise HTTPException(422, "请选择全A股、行业或我的自选。")
    kind = scope["kind"]
    allowed = {"kind", "codes"} if kind == "watchlist" else {"kind", "industry_code"} if kind == "industry" else {"kind"}
    if set(scope) != allowed:
        raise HTTPException(422, "股票范围字段不匹配，不能同时指定其他股票池。")
    if kind == "industry":
        if not isinstance(scope["industry_code"], str) or not _BOARD.fullmatch(scope["industry_code"]):
            raise HTTPException(422, "请选择有效的行业。")
        return dict(scope)
    if kind == "watchlist":
        codes = scope["codes"]
        if not isinstance(codes, list) or not codes:
            raise HTTPException(422, "我的自选为空，请先添加股票。")
        normalized = []
        for code in codes:
            if not isinstance(code, str) or not re.fullmatch(r"\d{6}(?:\.(?:SH|SZ|BJ))?", code):
                raise HTTPException(422, "自选股票代码无效。")
            symbol = _symbol(code)
            try:
                verified = _a_share_identity({"f12": symbol[:6], "f13": 1 if symbol.endswith(".SH") else 0})
            except ScopeUnavailableError as exc:
                raise HTTPException(422, "我的自选仅支持标准A股代码。") from exc
            if verified != symbol:
                raise HTTPException(422, "自选股票代码与交易所不匹配。")
            if symbol not in normalized:
                normalized.append(symbol)
        return {"kind": kind, "codes": normalized}
    return {"kind": kind}


def _complete_rows(fs: str) -> list[dict[str, Any]]:
    from backtest.loaders.eastmoney_client import get_json
    from src.tools.market_screener_tool import _CLIST_URL

    rows = []
    seen = set()
    total = None
    page = 1
    while total is None or len(rows) < total:
        try:
            payload = get_json(_CLIST_URL, params={"pn": str(page), "pz": str(_PAGE_SIZE),
                "po": "0", "fid": "f12", "fs": fs, "fields": "f12,f13,f14", "fltt": "2"})
        except Exception as exc:
            raise ScopeUnavailableError("scope_provider_unavailable", "股票范围暂时无法读取，请稍后重试或使用我的自选。") from exc
        data = payload.get("data") if isinstance(payload, dict) else None
        if not isinstance(data, dict) or type(data.get("total")) is not int or data["total"] < 1:
            raise ScopeUnavailableError("scope_provider_unavailable", "数据源没有返回可用的完整股票范围，请稍后重试。")
        if total is None:
            total = data["total"]
        elif total != data["total"]:
            raise ScopeUnavailableError("scope_members_changed", "股票范围在读取期间发生变化，请重新发起。")
        part = data.get("diff")
        if isinstance(part, dict):
            part = list(part.values())
        expected = min(_PAGE_SIZE, total - len(rows))
        if not isinstance(part, list) or len(part) != expected:
            raise ScopeUnavailableError("scope_members_incomplete", "股票范围返回不完整，本次没有开始计算，请稍后重试。")
        for row in part:
            if (not isinstance(row, dict) or not isinstance(row.get("f12"), str) or not row["f12"]
                    or "f13" not in row):
                raise ScopeUnavailableError("scope_identity_invalid", "股票范围缺少可靠的证券身份，请稍后重试。")
            key = (str(row.get("f13")), row["f12"])
            if key in seen:
                raise ScopeUnavailableError("scope_members_incomplete", "股票范围分页重复，本次没有开始计算，请稍后重试。")
            seen.add(key)
            rows.append(row)
        page += 1
    return rows


def industry_catalog() -> dict[str, Any]:
    from src.tools.sector_tool import _RANKING_FS

    rows = _complete_rows(_RANKING_FS)
    items = []
    for row in rows:
        if not _BOARD.fullmatch(row["f12"]) or not isinstance(row.get("f14"), str) or not row["f14"].strip():
            raise ScopeUnavailableError("scope_industry_invalid", "行业目录返回不完整，请稍后重试。")
        items.append({"code": row["f12"], "name": row["f14"].strip()})
    stamp = _stamp()
    return {"items": items, "source": "eastmoney", "as_of": stamp[:10], "fetched_at": stamp,
        "taxonomy": "东方财富行业"}


def _a_share_identity(row: dict[str, Any]) -> str:
    code = row["f12"]
    market = str(row.get("f13"))
    if re.fullmatch(r"6[0-9]{5}", code) and market == "1":
        return code + ".SH"
    if re.fullmatch(r"(?:00|30)[0-9]{4}", code) and market == "0":
        return code + ".SZ"
    if re.fullmatch(r"(?:[48][0-9]{5}|92[0-9]{4})", code) and market == "0":
        return code + ".BJ"
    raise ScopeUnavailableError("scope_identity_invalid", "A股目录包含无法核实的证券身份，本次没有开始计算。")


def resolve_scope(scope: dict[str, Any]) -> dict[str, Any]:
    from src.tools.market_screener_tool import _MARKET_FS

    scope = validate_scope(scope)
    extra = {}
    if scope["kind"] == "watchlist":
        codes = scope["codes"]
        source = "watchlist"
    else:
        industry = None
        directory = None
        if scope["kind"] == "industry":
            directory = industry_catalog()
            industry = next((row for row in directory["items"] if row["code"] == scope["industry_code"]), None)
            if industry is None:
                raise ScopeUnavailableError("scope_industry_not_found", "所选行业已不在当前行业目录中，请重新选择。")
        all_rows = _complete_rows(_MARKET_FS["a"])
        a_shares = {(str(row["f13"]), row["f12"]): _a_share_identity(row) for row in all_rows}
        source = "eastmoney"
        if scope["kind"] == "all_a":
            codes = list(a_shares.values())
        else:
            members = _complete_rows("b:" + industry["code"])
            # Board membership can contain B-shares and other securities. Only
            # the complete native A-share universe establishes A-share identity.
            codes = [a_shares[(str(row.get("f13")), row["f12"])] for row in members
                if (str(row.get("f13")), row["f12"]) in a_shares]
            extra = {"industry_code": industry["code"], "industry_name": industry["name"],
                "taxonomy": directory["taxonomy"], "provider_members": len(members),
                "excluded_non_a": len(members) - len(codes)}
    if not codes:
        raise ScopeUnavailableError("scope_has_no_stocks", "所选范围没有可用A股，请更换行业或检查我的自选。")
    stamp = _stamp()
    snapshot = {"kind": scope["kind"], "source": source, "as_of": stamp[:10], "fetched_at": stamp,
        "membership_basis": "current_snapshot", "point_in_time": False, "count": len(codes),
        "codes": codes, "identity": _hash({"source": source, "codes": codes}), **extra}
    snapshot["snapshot_sha256"] = _hash(snapshot)
    return snapshot


def scope_metadata(snapshot: dict[str, Any]) -> dict[str, Any]:
    return {key: value for key, value in snapshot.items() if key != "codes"}


def write_scope(run_dir: Path, snapshot: dict[str, Any]) -> None:
    (run_dir / "mona_strategy_scope.json").write_text(
        json.dumps(snapshot, ensure_ascii=False, indent=2, allow_nan=False) + "\n", encoding="utf-8")


def read_scope(run_dir: Path) -> dict[str, Any] | None:
    path = run_dir / "mona_strategy_scope.json"
    if not path.exists():
        return None
    from src.api.mona_operations import _read_bounded
    from src.api.mona_reads import _has_linked_component
    from src.tools.path_utils import safe_run_dir

    root = safe_run_dir(str(run_dir))
    if _has_linked_component(path, root) or not path.is_file() or not path.resolve().is_relative_to(root):
        raise ValueError("invalid_strategy_scope_snapshot")
    snapshot = json.loads(_read_bounded(path, 16 * 1024 * 1024, "scope snapshot"))
    if (not isinstance(snapshot, dict) or not isinstance(snapshot.get("codes"), list)
            or snapshot.get("count") != len(snapshot["codes"])
            or snapshot.get("snapshot_sha256") != _hash({key: value for key, value in snapshot.items() if key != "snapshot_sha256"})
            or snapshot.get("identity") != _hash({"source": snapshot["source"], "codes": snapshot["codes"]})):
        raise ValueError("strategy_scope_snapshot_mismatch")
    return snapshot


def scope_budget(snapshot: dict[str, Any], source: str, native_timeout: float | None) -> dict[str, Any]:
    from backtest.loaders.eastmoney_client import _min_interval

    # Two requests per remote symbol covers qfq/raw cold loading; one extra
    # cold-load allowance covers network/retries while the native budget keeps
    # its calculation allowance. This is a deadline, not a duration estimate.
    cold = 0.0 if source == "local" else 2 * snapshot["count"] * max(1.0, _min_interval())
    return {"policy": "native_plus_two_cold_load_allowances", "source": source,
        "native_timeout_seconds": native_timeout, "cold_load_floor_seconds": cold,
        "timeout_seconds": None if native_timeout is None else native_timeout + 2 * cold}


def scoped_timeout(run_dir: Path, native_timeout: float | None) -> float | None:
    snapshot = read_scope(run_dir)
    if snapshot is None:
        return native_timeout
    config = json.loads((run_dir / "config.json").read_text(encoding="utf-8"))
    return scope_budget(snapshot, config.get("source", "tushare"), native_timeout)["timeout_seconds"]


def scoped_result_limit(run_dir: Path, *, artifact: bool = False) -> int:
    snapshot = read_scope(run_dir)
    if snapshot is None:
        return 2 * 1024 * 1024
    # The operation response contains both raw and parsed results; reserve room
    # for both beneath the host response boundary. Member lists stay on disk.
    ceiling = (12 if artifact else 6) * 1024 * 1024
    return min(ceiling, max(2 * 1024 * 1024, snapshot["count"] * 768))


def coverage_result(snapshot: dict[str, Any], loaded: list[str], evaluated: list[str], source: str) -> dict[str, Any]:
    requested = snapshot["codes"]
    loaded_set = set(loaded) & set(requested)
    evaluated_set = set(evaluated) & loaded_set
    missing = [{"symbol": code, "reason": "source_market_unavailable" if source == "tencent" and code.endswith(".BJ")
        else "price_data_missing" if code not in loaded_set else "strategy_signal_missing"}
        for code in requested if code not in evaluated_set]
    return {"coverage": {"requested": len(requested), "loaded": len(loaded_set),
        "evaluated": len(evaluated_set), "missing": len(missing), "complete": not missing}, "missing": missing}


def write_backtest_coverage(run_dir: Path, loaded: list[str], evaluated: list[str], source: str) -> None:
    snapshot = read_scope(run_dir)
    if snapshot is None:
        return
    result = coverage_result(snapshot, loaded, evaluated, source)
    artifacts = run_dir / "artifacts"
    artifacts.mkdir(exist_ok=True)
    (artifacts / "scope_coverage.json").write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def add_scope_result(run_dir: Path, result: dict[str, Any], *, include_missing: bool = False) -> dict[str, Any]:
    snapshot = read_scope(run_dir)
    if snapshot is None:
        return result
    result["scope"] = scope_metadata(snapshot)
    coverage = run_dir / "artifacts/scope_coverage.json"
    if coverage.is_file():
        from src.api.mona_operations import _read_bounded
        saved = json.loads(_read_bounded(coverage, 16 * 1024 * 1024, "scope coverage"))
        result["coverage"] = saved["coverage"]
        if include_missing:
            result["missing"] = saved["missing"]
        if not saved["coverage"]["complete"]:
            result["note"] = ("所选范围没有可用于本次计算的股票，本次计算未完成。请检查行情来源、日期或补齐本地数据。"
                if saved["coverage"]["evaluated"] == 0 else
                "仅完成所选范围中的部分股票，不能视为全范围完整结果。请检查行情来源、日期或补齐本地数据。")
    elif result.get("status") == "error":
        result["note"] = "本次计算未完成。请检查行情来源和日期；使用本地数据时需补齐所选范围。"
    result["scope_note"] = "范围成员来自本次当前快照；历史回测未还原逐日成分，存在生存者偏差。"
    return result


def add_scan_coverage(run_dir: Path, result: dict[str, Any], loaded: list[str], evaluated: list[str], source: str) -> dict[str, Any]:
    snapshot = read_scope(run_dir)
    if snapshot is None:
        return result
    saved = coverage_result(snapshot, loaded, evaluated, source)
    reasons = {row["symbol"]: row["reason"] for row in result.get("missing", [])}
    for row in saved["missing"]:
        if row["reason"] != "source_market_unavailable" and row["symbol"] in reasons:
            row["reason"] = reasons[row["symbol"]]
    artifacts = run_dir / "artifacts"
    artifacts.mkdir(exist_ok=True)
    (artifacts / "scope_coverage.json").write_text(json.dumps(saved, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    result.update(saved)
    return add_scope_result(run_dir, result, include_missing=True)
